function collectLocalTsFiles(root: string): string[] {
  const out: string[] = [];
  const visitedRealDirs = new Set<string>();
  const walk = (dir: string): void => {
    let realDir: string;
    try {
      realDir = fs.realpathSync(dir);
    } catch (e: unknown) {
      throw sourceReadFailed(dir, `local build realpath failed: ${String(e)}`);
    }
    if (visitedRealDirs.has(realDir)) return; // symlink cycle detected
    visitedRealDirs.add(realDir);
    let entries: import('node:fs').Dirent[];
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch (e: unknown) {
      throw sourceReadFailed(dir, `local build readdir failed: ${String(e)}`);
    }
    for (const e of entries) {
      if (e.name === '.' || e.name === '..') continue;
      const abs = path.join(dir, e.name);
      if (e.isDirectory()) {
        if (LOCAL_BUILD_SKIPS.has(e.name)) continue;
        walk(abs);
      } else if (e.isFile() && e.name.endsWith('.ts') && !e.name.endsWith('.d.ts')) {
        out.push(abs);
      }
    }
  };
  walk(root);
  return out;
}

