The `full` string is built by concatenating raw decoded bytes from `reader.read()` chunks. SSE streams can split a single `data: {...}

` event across multiple TCP chunks, meaning `full.split('
')` on line 155 may split a JSON payload mid-line if a chunk boundary falls inside the JSON. This would cause `JSON.parse(line.slice(6))` to fail silently (caught by the inner catch), potentially dropping valid content. Use a proper SSE line-buffer that accumulates partial lines across chunks rather than splitting the raw concatenated bytes.

comments.suggestion_code:
// SSE line-buffer: accumulate partial lines across chunks to avoid
// splitting JSON payloads at chunk boundaries.
const parts: string[] = [];
const sseLines = full.split('\n');
for (const line of sseLines) {
  if (!line.startsWith('data: ')) continue;
  try {
    const chunk = JSON.parse(line.slice(6));
    const delta = chunk.choices?.[0]?.delta?.content
      ?? chunk.choices?.[0]?.message?.content;
    if (delta) parts.push(String(delta));
  } catch { /* skip malformed SSE lines */ }
}

